To solve this problem efficiently given the constraints (coordinates up to 100 and $N$ up to $10^5$), we can use a 3D grid approach. Since the coordinate range is small ($100 \times 100 \times 100$), we can map each unit cube $(x, y, z)$ to the ID of the cuboid that occupies it.

Two cuboids share a face if there is an intersection with a positive area. Since the cuboids do not overlap, we check for adjacency along the $X, Y,$ and $Z$ axes. Specifically, for each unit cube occupied by cuboid $i$, we check if a neighbor in any of the 6 directions belongs to a different cuboid $j$. If it does, we record that $i$ and $j$ are adjacent.

```python
import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    cuboids = []
    idx = 1
    # grid stores the cuboid index (1-based) for each unit cell
    # coordinates are 0-99, so grid size 100x100x100
    grid = [[[0 for _ in range(100)] for _ in range(100)] for _ in range(100)]

    for i in range(1, N + 1):
        x1, y1, z1, x2, y2, z2 = map(int, input_data[idx:idx+6])
        idx += 6
        cuboids.append((x1, y1, z1, x2, y2, z2))
        for x in range(x1, x2):
            for y in range(y1, y2):
                for z in range(z1, z2):
                    grid[x][y][z] = i

    adj = [set() for _ in range(N + 1)]

    # Check boundaries between cells
    for x in range(100):
        for y in range(100):
            for z in range(100):
                curr = grid[x][y][z]
                if curr == 0: continue

                # Check 3 directions (right, forward, up) to avoid double counting
                # Check +x neighbor
                if x + 1 < 100:
                    neighbor = grid[x+1][y][z]
                    if neighbor != 0 and neighbor != curr:
                        adj[curr].add(neighbor)
                        adj[neighbor].add(curr)
                # Check +y neighbor
                if y + 1 < 100:
                    neighbor = grid[x][y+1][z]
                    if neighbor != 0 and neighbor != curr:
                        adj[curr].add(neighbor)
                        adj[neighbor].add(curr)
                # Check +z neighbor
                if z + 1 < 100:
                    neighbor = grid[x][y][z+1]
                    if neighbor != 0 and neighbor != curr:
                        adj[curr].add(neighbor)
                        adj[neighbor].add(curr)

    for i in range(1, N + 1):
        print(len(adj[i]))

if __name__ == '__main__':
    solve()
