import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # Parse the 3 polyominoes from the input
    # Each polyomino is a list of (r, c) tuples relative to their top-left-most occurrence
    polys = []
    for i in range(3):
        grid = input_data[i*4 : (i+1)*4]
        coords = []
        for r in range(4):
            for c in range(4):
                if grid[r][c] == '#':
                    coords.append((r, c))
        # Normalize: shift to top-left corner (0,0)
        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)
        norm = tuple(sorted((r - min_r, c - min_c) for r, c in coords))
        polys.append(norm)

    def rotate(coords):
        # Rotate 90 deg clockwise: (r, c) -> (c, -r)
        rotated = [(c, -r) for r, c in coords]
        min_r = min(r for r, c in rotated)
        min_c = min(c for r, c in rotated)
        return tuple(sorted((r - min_r, c - min_c) for r, c in rotated))

    # Generate all unique rotations for each polyomino
    poly_variants = []
    for p in polys:
        variants = set()
        curr = p
        for _ in range(4):
            variants.add(curr)
            curr = rotate(curr)
        poly_variants.append(list(variants))

    # Backtracking search
    # grid_mask: bitmask of 16 cells (4x4)
    def backtrack(idx, grid_mask):
        if idx == 3:
            return grid_mask == (1 << 16) - 1

        for variant in poly_variants[idx]:
            # Try all valid offsets (dr, dc)
            for dr in range(4):
                for dc in range(4):
                    new_mask = grid_mask
                    valid = True
                    for r, c in variant:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 4 and 0 <= nc < 4:
                            pos = nr * 4 + nc
                            if not (new_mask & (1 << pos)):
                                new_mask |= (1 << pos)
                            else:
                                valid = False
                                break
                        else:
                            valid = False
                            break
                    if valid:
                        if backtrack(idx + 1, new_mask):
                            return True
        return False

    if backtrack(0, 0):
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()
```

To solve this problem, we need to calculate the expected number of green connected components after changing one red cell to green.
Let $C$ be the number of existing green connected components.
When we turn a red cell $(i, j)$ green:
1. The number of components becomes $C + 1 - (\text{number of distinct existing green components adjacent to } (i, j))$.
2. We sum this value over all red cells and divide by the total number of red cells.

We use a Disjoint Set Union (DSU) or simple DFS/BFS to identify and label existing green connected components.

```python
import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H, W = int(input_data[0]), int(input_data[1])
    grid = input_data[2:]

    MOD = 998244353

    comp = [[-1 for _ in range(W)] for _ in range(H)]
    comp_id = 0

    def get_neighbors(r, c):
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Identify existing green components
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#' and comp[r][c] == -1:
                stack = [(r, c)]
                comp[r][c] = comp_id
                while stack:
                    curr_r, curr_c = stack.pop()
                    for nr, nc in get_neighbors(curr_r, curr_c):
                        if grid[nr][nc] == '#' and comp[nr][nc] == -1:
                            comp[nr][nc] = comp_id
                            stack.append((nr, nc))
                comp_id += 1

    total_components = comp_id
    red_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                red_cells.append((r, c))

    sum_new_components = 0
    for r, c in red_cells:
        neighbor_comps = set()
        for nr, nc in get_neighbors(r, c):
            if grid[nr][nc] == '#':
                neighbor_comps.add(comp[nr][nc])

        # New count = C + 1 - (number of unique adjacent components)
        sum_new_components += (total_components + 1 - len(neighbor_comps))

    num_red = len(red_cells)
    # Expected value = sum_new_components / num_red mod 998244353
    ans = (sum_new_components * pow(num_red, MOD - 2, MOD)) % MOD
    print(ans)

if __name__ == '__main__':
    solve()
```

To solve this problem, we need to find the shortest walk that visits all vertices. Given the constraints ($N \le 20$), we can use the Floyd-Warshall algorithm to compute the all-pairs shortest paths and then use dynamic programming with bitmasking to find the minimum cost to visit all nodes.

```python
import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    inf = float('inf')
    # dist[i][j] stores the minimum weight to go from i to j
    dist = [[inf] * N for _ in range(N)]

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall to get all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != inf and dist[k][j] != inf:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # dp[mask][last_node] = min cost to have visited vertices in mask, ending at last_node
    dp = [[inf] * N for _ in range(1 << N)]

    # Base case: start at any node
    for i in range(N):
        dp[1 << i][i] = 0

    # DP transitions
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == inf:
                continue
            for v in range(N):
                if dist[u][v] == inf:
                    continue
                new_mask = mask | (1 << v)
                if dp[new_mask][v] > dp[mask][u] + dist[u][v]:
                    dp[new_mask][v] = dp[mask][u] + dist[u][v]

    ans = inf
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == inf:
        print("No")
    else:
        print(ans)

if __name__ == '__main__':
    solve()
```

