def count_beautiful_integers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def solve(n: int) -> int:
        s = str(n)
        length = len(s)

        @lru_cache(None)
        def dp(idx, even_cnt, odd_cnt, rem, is_less, is_started):
            if idx == length:
                return 1 if (is_started and even_cnt == odd_cnt and rem == 0) else 0

            res = 0
            # Option 1: Still leading zeros
            if not is_started:
                res += dp(idx + 1, 0, 0, 0, True, False)

            # Option 2: Place a digit
            limit = int(s[idx]) if not is_less else 9
            for d in range(1 if not is_started else 0, limit + 1):
                new_is_less = is_less or (d < limit)
                new_even = even_cnt + (1 if d % 2 == 0 else 0)
                new_odd = odd_cnt + (1 if d % 2 != 0 else 0)
                new_rem = (rem * 10 + d) % k
                res += dp(idx + 1, new_even, new_odd, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, 0, False, False)

    # The problem constraints specify numbers up to 10^9. 
    # Digit DP naturally counts up to n inclusive.
    return solve(high) - solve(low - 1)
