To solve this problem, we need to precompute the minimum changes required to make any substring `s[i:j+1]` a semi-palindrome. A string of length `n` is a semi-palindrome if there exists a divisor `d` of `n` (where `1 <= d < n`) such that for each remainder `r` from `0` to `d-1`, the characters at indices `r, r+d, r+2d, ...` form a palindrome.

Here is the implementation:

```python
def solve(s: str, k: int) -> int:
    n = len(s)

    # Precompute divisors for each length from 1 to n
    divs = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for d in range(1, i):
            if i % d == 0:
                divs[i].append(d)

    # cost[i][j] will store the min changes to make s[i:j+1] a semi-palindrome
    cost = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            sub = s[i : j + 1]

            if length == 1:
                cost[i][j] = 1 # Not a semi-palindrome by definition d < len
                continue

            min_changes = float('inf')
            # Try all possible divisors d
            for d in divs[length]:
                current_d_changes = 0
                # For each divisor, check all groups
                for r in range(d):
                    group = sub[r::d]
                    # Make group a palindrome
                    for idx in range(len(group) // 2):
                        if group[idx] != group[len(group) - 1 - idx]:
                            current_d_changes += 1
                min_changes = min(min_changes, current_d_changes)
            cost[i][j] = min_changes

    # dp[p][i] = min changes partitioning s[0:i] into p substrings
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for p in range(1, k + 1):
        for i in range(1, n + 1):
            # Try last partition ending at i starting at j
            for j in range(p - 1, i):
                dp[p][i] = min(dp[p][i], dp[p - 1][j] + cost[j][i - 1])

    return dp[k][n]
```

