    # Precompute all substrings for each word and check their existence in other words
    # Since n and length are small (<= 20), we can iterate through all substrings

    def get_all_substrings(s):
        subs = set()
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                subs.add(s[i:j])
        return subs

    # all_others[i] stores a set of all substrings present in any string other than arr[i]
    all_others = []
    for i in range(n):
        others_subs = set()
        for j in range(n):
            if i == j:
                continue
            others_subs.update(get_all_substrings(arr[j]))
        all_others.append(others_subs)

    answer = []
    for i in range(n):
        s = arr[i]
        n_len = len(s)
        found_subs = []

        # Check by length first (1 to n), then lexicographically
        for length in range(1, n_len + 1):
            candidates = []
            for start in range(n_len - length + 1):
                sub = s[start : start + length]
                # Check if this substring exists in any other string
                if sub not in all_others[i]:
                    candidates.append(sub)

            if candidates:
                # We found the shortest length(s), return the lexicographically smallest
                answer.append(min(candidates))
                break
        else:
            # No unique substring found
            answer.append("")

    return answer
