    # 3. Adjacent cells:
    #    - Bottom and right of top-left 3x3:
    #      (0,3), (1,3), (2,3), (3,3), (3,2), (3,1), (3,0) are all '.'
    #    - Top and left of bottom-right 3x3:
    #      (5,8), (5,7), (5,6), (5,5), (6,5), (7,5), (8,5) are all '.'

    def is_tak_code(r, c):
        # Check Top-left 3x3
        for i in range(r, r + 3):
            for j in range(c, c + 3):
                if grid[i][j] != '#':
                    return False

        # Check Bottom-right 3x3
        for i in range(r + 6, r + 9):
            for j in range(c + 6, c + 9):
                if grid[i][j] != '#':
                    return False

        # Check surrounding whites
        # Boundary white cells for top-left 3x3
        for i in range(r, r + 4):
            if grid[i][c + 3] != '.': return False
        for j in range(c, c + 3):
            if grid[r + 3][j] != '.': return False

        # Boundary white cells for bottom-right 3x3
        for i in range(r + 5, r + 9):
            if grid[i][c + 5] != '.': return False
        for j in range(c + 6, c + 9):
            if grid[r + 5][j] != '.': return False

        return True

