def findPrimePairs(n: int) -> list[list[int]]:
    if n < 4:
        return []

    # Sieve of Eratosthenes to find all primes up to n
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False

