def shortestSuperstring(a, b, c):
    from itertools import permutations

    def merge(s1, s2):
        """Returns the shortest string that starts with s1 and ends with s2."""
        if s2 in s1:
            return s1
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def get_super(seq):
        """Merges a sequence of strings in order."""
        res = seq[0]
        for i in range(1, len(seq)):
            res = merge(res, seq[i])
        return res

    # A string containing a, b, c must be formed by merging them in some order.
    # Because one might be a substring of another, we first simplify the set.
    strings = [a, b, c]
    # Remove strings that are already contained in another
    unique_strings = []
    for i in range(3):
        is_substring = False
        for j in range(3):
            if i != j and strings[i] in strings[j]:
                is_substring = True
                break
        if not is_substring:
            unique_strings.append(strings[i])

    # If after filtering some are identical, keep unique ones
    unique_strings = list(set(unique_strings))

    candidates = []
    # Permute the remaining strings
    for p in permutations(unique_strings):
        candidates.append(get_super(p))

    # Also consider cases where a string was a substring of another (covered by logic above)
    # But just in case, we add the original superstrings if they contain all 3
    for p in permutations([a, b, c]):
        candidates.append(get_super(p))

    # Find min length, then lexicographically smallest
    min_len = min(len(s) for s in candidates)
    best_candidates = [s for s in candidates if len(s) == min_len]

    return min(best_candidates)
