import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H, W, T = map(int, input_data[:3])
    grid = input_data[3:]

    start = None
    goal = None
    candies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'G':
                goal = (r, c)
            elif grid[r][c] == 'o':
                candies.append((r, c))

    # Points of interest: Start, Goal, and all Candies
    points = [start] + candies + [goal]
    num_points = len(points)

    # BFS to calculate distances between all pairs of POIs
    def get_distances(start_node):
        dist = [[-1] * W for _ in range(H)]
        dist[start_node[0]][start_node[1]] = 0
        queue = deque([start_node])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))
        return dist

    adj = [[-1] * num_points for _ in range(num_points)]
    for i in range(num_points):
        dists = get_distances(points[i])
        for j in range(num_points):
            adj[i][j] = dists[points[j][0]][points[j][1]]

    num_candies = len(candies)
    # dp[mask][i] = min distance to reach candy i, having visited set 'mask'
    # Start is index 0, candies are 1 to num_candies, goal is index num_candies+1
    dp = [[float('inf')] * (num_candies + 1) for _ in range(1 << num_candies)]

    for i in range(num_candies):
        if adj[0][i+1] != -1:
            dp[1 << i][i+1] = adj[0][i+1]

    for mask in range(1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i+1] == float('inf'): continue
            for next_candy in range(num_candies):
                if not (mask & (1 << next_candy)):
                    if adj[i+1][next_candy+1] != -1:
                        new_dist = dp[mask][i+1] + adj[i+1][next_candy+1]
                        if new_dist < dp[mask | (1 << next_candy)][next_candy+1]:
                            dp[mask | (1 << next_candy)][next_candy+1] = new_dist

    # Final check: reach goal from each candy configuration
    max_candies = -1
    if adj[0][num_candies] != -1 and adj[0][num_candies] <= T:
        max_candies = 0

    for mask in range(1 << num_candies):
        count = bin(mask).count('1')
        for i in range(num_candies):
            if dp[mask][i+1] != float('inf'):
                if adj[i+1][num_candies] != -1:
                    if dp[mask][i+1] + adj[i+1][num_candies] <= T:
                        max_candies = max(max_candies, count)

    print(max_candies)

