def minEqualSum(nums1, nums2):
    """
    To make the sum of both arrays equal, we need to replace each 0 with at least 1.
    Let s1 and s2 be the current sums, and z1 and z2 be the number of zeros.
    The minimum sum for an array is: current_sum + number_of_zeros * 1.

    If an array has no zeros, its sum is fixed. If it has zeros, it can reach any sum 
    starting from current_sum + number_of_zeros up to infinity.
    """
    s1, z1 = 0, 0
    for x in nums1:
        if x == 0:
            z1 += 1
        else:
            s1 += x

    s2, z2 = 0, 0
    for x in nums2:
        if x == 0:
            z2 += 1
        else:
            s2 += x

    min_s1 = s1 + z1
    min_s2 = s2 + z2

    # Case 1: Both arrays have no zeros. Sums must be equal.
    if z1 == 0 and z2 == 0:
        return s1 if s1 == s2 else -1

    # Case 2: One array has no zeros.
    if z1 == 0:
        # If min_s2 <= s1, we can adjust the zeros in nums2 to reach s1.
        return s1 if s1 >= min_s2 else -1

    if z2 == 0:
        return s2 if s2 >= min_s1 else -1

    # Case 3: Both arrays have zeros. We can reach any sum >= max(min_s1, min_s2).
    return max(min_s1, min_s2)
