def countPowerfulIntegers(start: int, finish: int, limit: int, s: str) -> int:
    """
    Calculates the number of powerful integers in range [start, finish]
    using digit DP. An integer is powerful if it ends with s and digits <= limit.
    """

    def solve(n: int) -> int:
        s_n = str(n)
        len_n = len(s_n)
        len_s = len(s)

        # If the number is smaller than the smallest possible number ending in s
        if len_n < len_s:
            return 0

        memo = {}

        def dp(idx, is_less, is_started):
            # Base case: we reached the end of the number string
            if idx == len_n:
                return 1 if is_started else 0

            state = (idx, is_less, is_started)
            if state in memo:
                return memo[state]

            res = 0
            # If we are within the suffix part
            if idx >= len_n - len_s:
                digit_in_s = int(s[idx - (len_n - len_s)])

                # Check if this digit position is valid for the suffix
                if not is_less and digit_in_s > int(s_n[idx]):
                    return 0
                if digit_in_s > limit:
                    return 0

                res = dp(idx + 1, is_less or (digit_in_s < int(s_n[idx])), True)
            else:
                # We are in the prefix part
                upper = int(s_n[idx]) if not is_less else 9

                for digit in range(upper + 1):
                    if digit > limit:
                        continue

                    new_is_less = is_less or (digit < upper)
                    # If it's a leading zero, we continue not-started
                    if not is_started and digit == 0:
                        res += dp(idx + 1, True, False)
                    else:
                        res += dp(idx + 1, new_is_less, True)

            memo[state] = res
            return res

        return dp(0, False, False)

    return solve(finish) - solve(start - 1)
