def countMatchingSubarrays(nums, pattern):
    """
    Counts the number of subarrays in nums that match the given pattern.
    """
    n = len(nums)
    m = len(pattern)
    count = 0

    # A subarray of size m + 1 starts at index i and ends at i + m.
    # The valid starting indices i range from 0 to n - (m + 1).
    for i in range(n - m):
        match = True
        for k in range(m):
            if pattern[k] == 1:
                if not (nums[i + k + 1] > nums[i + k]):
                    match = False
                    break
            elif pattern[k] == 0:
                if not (nums[i + k + 1] == nums[i + k]):
                    match = False
                    break
            elif pattern[k] == -1:
                if not (nums[i + k + 1] < nums[i + k]):
                    match = False
                    break

        if match:
            count += 1

